61	// Type traits to abstract differences between standard types and Float16Tag
62	template<class T>
63	struct DTypeTraits
64	{
65	    static bool matches(const py::dtype &dtbase)
66	    {
67	        return dtbase.equal(py::dtype::of<T>());
68	    }
69	
70	    static py::dtype create()
71	    {
72	        return py::dtype::of<T>();
73	    }
74	
75	    static constexpr int itemsize()
76	    {
77	        return sizeof(T);
78	    }
79	
80	    static int bits_per_component(int itemsize_param)
81	    {
82	        return itemsize_param * 8;
83	    }
84	
85	    static nvcv::DataKind infer_kind()
86	    {
87	        if (IsComplex<T>::value)
88	            return nvcv::DataKind::COMPLEX;
89	        else if (std::is_floating_point_v<T>)
90	            return nvcv::DataKind::FLOAT;
91	        else if (std::is_signed_v<T>)
92	            return nvcv::DataKind::SIGNED;
93	        else if (std::is_unsigned_v<T>)
94	            return nvcv::DataKind::UNSIGNED;
95	        else
96	        {
97	            NVCV_ASSERT(!"Invalid type");
98	        }
99	    }
100	};
