132	template<class T>
133	bool FindDataType(const py::dtype &dt, nvcv::DataType *dtype)
134	{
135	    int       nchannels = 1;
136	    py::dtype dtbase    = dt;
137	    if (hasattr(dt, "subdtype"))
138	    {
139	        py::object obj = dt.attr("subdtype");
140	        if (!obj.equal(py::none()))
141	        {
142	            auto subdt = py::cast<py::tuple>(obj);
143	            if (subdt.size() != 2)
144	            {
145	                // Malformed? subdtype tuple must have 2 elements.
146	                return false;
147	            }
148	            dtbase = subdt[0];
149	
150	            // only 1d shape for now
151	            auto shape = py::cast<py::tuple>(subdt[1]);
152	            if (shape.size() >= 2)
153	            {
154	                return false;
155	            }
156	
157	            nchannels = shape.empty() ? 1 : py::cast<int>(shape[0]);
158	        }
159	    }
160	
161	    auto itemsize = static_cast<int>(dtbase.itemsize());
162	
163	    // Use traits to check if this type matches
164	    if (!DTypeTraits<T>::matches(dtbase))
165	    {
166	        return false;
167	    }
168	
169	    // get the data kind from the traits
170	    auto                dataKind = DTypeTraits<T>::infer_kind();
171	    nvcv::PackingParams pp       = {};
172	    pp.byteOrder                 = nvcv::ByteOrder::MSB;
173	
174	    switch (nchannels)
175	    {
176	    case 1:
177	        pp.swizzle = nvcv::Swizzle::S_X000;
178	        break;
179	    case 2:
180	        pp.swizzle = nvcv::Swizzle::S_XY00;
181	        break;
182	    case 3:
183	        pp.swizzle = nvcv::Swizzle::S_XYZ0;
184	        break;
185	    case 4:
186	        pp.swizzle = nvcv::Swizzle::S_XYZW;
187	        break;
188	    default:
189	        NVCV_ASSERT(!"Invalid number of channels");
190	    }
191	
192	    // Use traits to get bits per component
193	    for (int i = 0; i < nchannels; ++i)
194	    {
195	        pp.bits[i] = DTypeTraits<T>::bits_per_component(itemsize);
196	    }
197	
198	    nvcv::Packing packing = MakePacking(pp);
199	
200	    // Finally, infer the data type
201	    NVCV_ASSERT(dtype != nullptr);
202	    *dtype = nvcv::DataType{dataKind, packing};
203	    return true;
204	}
