108	                                  NVCVTensorBufferType bufType)
109	{
110	    NVCVTensorData tensorData = {};
111	
112	    // dtype ------------
113	    tensorData.dtype = static_cast<NVCVDataType>(py::cast<nvcv::DataType>(ToDType(ToNVCVDataType(tensor.dtype))));
114	
115	    // layout ------------
116	    if (layout)
117	    {
118	        tensorData.layout = static_cast<const NVCVTensorLayout &>(*layout);
119	    }
120	
121	    // rank ------------
122	    {
123	        // REVISIT: Add 0D support
124	        int rank = tensor.ndim == 0 ? 1 : tensor.ndim;
125	        if (rank < 1 || rank > NVCV_TENSOR_MAX_RANK)
126	        {
127	            throw std::invalid_argument(util::ConcatString("Number of dimensions must be between 1 and ",
128	                                                           NVCV_TENSOR_MAX_RANK, ", not ", rank));
129	        }
130	        tensorData.rank = rank;
131	    }
132	
133	    // shape ------------
134	    std::copy_n(tensor.shape, tensor.ndim, tensorData.shape);
135	
136	    // buffer type ------------
137	    if (IsCudaAccessible(tensor.device.device_type))
138	    {
139	        tensorData.bufferType = bufType;
140	    }
141	    else
142	    {
143	        throw TensorError("Only CUDA-accessible tensors are supported for now");
144	    }
145	
146	    NVCVTensorBufferStrided &dataStrided = tensorData.buffer.strided;
147	
148	    // stride ------------
149	    int elemStrideBytes = (tensor.dtype.bits * tensor.dtype.lanes + 7) / 8;
150	    for (int d = 0; d < tensor.ndim; ++d)
151	    {
152	        dataStrided.strides[d] = tensor.strides[d] * elemStrideBytes;
153	    }
154	
155	    // Memory buffer ------------
156	    dataStrided.basePtr = reinterpret_cast<NVCVByte *>(tensor.data) + tensor.byte_offset;
157	
158	    return tensorData;
159	}

